WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_111'), 'A learner clicks this link in the course syllabus:

https://app.codedev.test/courses/web-http/lessons?tab=notes#exercise-3

The access log of the web server shows:

203.0.113.57 "GET /courses/web-http/lessons?tab=notes HTTP/2" 200

Statement: "The server can read exercise-3 from this request and use it to decide which exercise to render."', 'single_choice'::question_type, 'False. The fragment (everything after #) is resolved by the browser and is never sent in the HTTP request, which is why the log line ends at ?tab=notes. Client-side code can read it from location.hash, but the server never sees it. A common misconception is that the whole URL travels to the server; if the server needs the value, put it in the path or the query string.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_111') AND order_index = 1)
    RETURNING id
)
