-- challenge chal_coding_whf_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_whf_122', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-1-2' AND is_deleted = false LIMIT 1), 'choose-method-and-status', 'Choose the method and status code', 'The CodeDev API team wants its conventions in one function, so every new route answers the same way. Write chooseResponse(operation) and return { method, status }.

operation is an object:
- action (required): exactly one of "list", "read", "create", "replace", "update", "delete" (lowercase).
- targetExists (boolean, default true): whether the item addressed by id exists. Used only by read, replace, update and delete. list and create target a collection, which always exists, so they ignore it.
- inputValid (boolean, default true): whether the request body passes validation. Used only by create, replace and update.
- conflict (boolean, default false): whether the change conflicts with existing data, such as a duplicate enrollment. Used only by create, replace and update.
Flags that an action does not use are ignored.

method: list and read -> "GET", create -> "POST", replace -> "PUT", update -> "PATCH", delete -> "DELETE".

status: the first matching rule wins.
1. targetExists is false (read, replace, update, delete) -> 404. The API assigns ids itself, so PUT never creates a missing item.
2. inputValid is false (create, replace, update) -> 422.
3. conflict is true (create, replace, update) -> 409.
4. Otherwise success: list 200 (also when nothing matches: an empty list is still 200), read 200, create 201, replace 200, update 200, delete 204.

Any other action (missing, misspelled, uppercase, or an HTTP method name such as "GET") -> throw an Error.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
