INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 1, 'Two separate questions decide every answer: which method does this action use, and which status rule matches first? What should an update answer when its id does not exist and its body is also invalid?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 2, 'Write the method lookup as a small object map from action to method, and reject actions that are not in it. Then apply the status rules in the order given, and for each rule check whether the action is one of those the rule applies to: list and create never answer 404, and read, list and delete never look at inputValid or conflict.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 3, 'The same pattern on a different API: a payments service maps charge -> POST and refund -> POST, then checks "account closed" (410) before "amount invalid" (422), and answers 201 otherwise. For { action: "refund", accountClosed: true, amountValid: false } the closed check matches first, so the answer is { method: "POST", status: 410 }; for { action: "charge" } it is { method: "POST", status: 201 }.');
