INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'Each action uses its method and its success status', '{"operations":[{"action":"list"},{"action":"read"},{"action":"create"},{"action":"replace"},{"action":"update"},{"action":"delete"}]}', '[{"method":"GET","status":200},{"method":"GET","status":200},{"method":"POST","status":201},{"method":"PUT","status":200},{"method":"PATCH","status":200},{"method":"DELETE","status":204}]', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'A learner with no enrollments gets 200 and an empty list, not 404', '{"operations":[{"action":"list","targetExists":false},{"action":"read","targetExists":false}]}', '[{"method":"GET","status":200},{"method":"GET","status":404}]', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'A duplicate enrollment is 409 and an invalid body is 422', '{"operations":[{"action":"create","conflict":true},{"action":"create","inputValid":false},{"action":"update","inputValid":false}]}', '[{"method":"POST","status":409},{"method":"POST","status":422},{"method":"PATCH","status":422}]', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'An unknown id is 404 for replace, update and delete; PUT never creates', '{"operations":[{"action":"replace","targetExists":false},{"action":"update","targetExists":false},{"action":"delete","targetExists":false}]}', '[{"method":"PUT","status":404},{"method":"PATCH","status":404},{"method":"DELETE","status":404}]', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'Rules apply in order: 404 before 422 before 409', '{"operations":[{"action":"update","targetExists":false,"inputValid":false,"conflict":true},{"action":"create","inputValid":false,"conflict":true},{"action":"replace","inputValid":false,"conflict":true},{"action":"replace","conflict":true},{"action":"update","targetExists":true,"inputValid":true,"conflict":true}]}', '[{"method":"PATCH","status":404},{"method":"POST","status":422},{"method":"PUT","status":422},{"method":"PUT","status":409},{"method":"PATCH","status":409}]', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'Flags an action does not use are ignored', '{"operations":[{"action":"read","inputValid":false,"conflict":true},{"action":"delete","inputValid":false,"conflict":true},{"action":"list","targetExists":false,"inputValid":false,"conflict":true},{"action":"create","targetExists":false}]}', '[{"method":"GET","status":200},{"method":"DELETE","status":204},{"method":"GET","status":200},{"method":"POST","status":201}]', 5, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_122'), 'Unknown, uppercase, HTTP-method or missing actions are rejected', '{"operations":[{"action":"remove"},{"action":"LIST"},{"action":"GET"},{"targetExists":true}]}', '["rejected","rejected","rejected","rejected"]', 5, false, true, 7);
