-- challenge chal_coding_whf_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_whf_132', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-1-3' AND is_deleted = false LIMIT 1), 'classify-http-failure', 'Classify an HTTP failure', 'The lesson player told learners "You are offline" when the API''s gateway answered with a 502 HTML page. The fix needs one pure function that says what kind of result came back, so the UI can show the right message. Write classifyResponse(result).

result is either a received response { status, body } (body can be anything; it is ignored, the status decides) or a request that got no response { networkError: "timeout" | "offline" | "aborted" | ... }.

Return one of these strings, using the first rule that matches:
1. result is null or not an object -> "network".
2. result has a networkError that is a non-empty string -> "network", even if a status is also present.
3. status is missing (undefined), null or 0 -> "network" (nothing usable came back; XMLHttpRequest and many libraries report status 0).
4. status is not an integer from 100 to 599 (for example the string "404", 404.5, -1, 600) -> "unexpected".
5. 200-299 -> "success"; 400 or 422 -> "validation"; 401 or 403 -> "auth"; 404 -> "not_found"; 500-599 -> "server".
6. Any other status (1xx, 3xx, and other 4xx such as 405, 409 or 429) -> "unexpected": this screen does not expect them, so it reports them instead of guessing.

The function must not throw for any of these inputs.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
