WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_211'), 'The admin app at https://admin.codedev.test calls the API with credentials: "include". Its console says the request was blocked by CORS policy. The backend developer runs:

$ curl -i https://api.codedev.test/admin/courses -H ''Cookie: session=<test session>''
HTTP/2 200
content-type: application/json
access-control-allow-origin: *
access-control-allow-credentials: true

[{"id":42,"title":"Web Application Fundamentals"}]

Statement: "Because curl receives 200 OK with the JSON, the API''s CORS configuration is correct, and the bug must be in the admin app''s fetch call."', 'single_choice'::question_type, 'False. curl does not implement CORS at all: it shows what the server sent, not whether a browser would let a page read it. The headers are the bug. For a request sent with credentials, the browser requires Access-Control-Allow-Origin to be exactly the page''s origin (https://admin.codedev.test) together with Access-Control-Allow-Credentials: true; the wildcard * is rejected in that mode. The common misconception is that a 200 in curl clears the server - it only proves the server answered.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_211') AND order_index = 1)
    RETURNING id
)
