WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_211'), 'The page https://app.codedev.test runs:

await fetch("https://api.codedev.test/progress/lesson-whf-2-1", {
  method: "PUT",
  credentials: "include",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ completed: true }),
});

No preflight result for this URL is cached yet.

Statement: "Before sending the PUT, the browser sends an OPTIONS request with Access-Control-Request-Method: PUT and Access-Control-Request-Headers: content-type, and that OPTIONS request carries no cookies."', 'single_choice'::question_type, 'True. The method PUT and the Content-Type value application/json both fall outside the CORS-safelisted set, so the browser must ask first with a preflight. The preflight describes the real request in Access-Control-Request-Method and Access-Control-Request-Headers (header names lowercased), and it is always sent without credentials, even when the real request uses credentials: "include". A common mistake is to put authentication in front of OPTIONS: the preflight then gets a 401 and the PUT is never sent.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_211') AND order_index = 2)
    RETURNING id
)
