-- challenge chal_coding_whf_212 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_whf_212', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-2-1' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-cors-headers', 'Spot the AI Mistake: CORS headers', 'An AI assistant was asked to "allow our web app and the admin app to call the API with cookies" and wrote corsHeaders(requestOrigin, allowlist). Since it shipped, every request the web app (https://app.codedev.test) and the admin app (https://admin.codedev.test) send with credentials: "include" fails with "blocked by CORS policy" in the console, while curl shows 200 OK. The security review adds that the helper''s answer is the same for any website that calls the API, and that a CDN in front of the API could serve one origin''s headers to another.

Fix corsHeaders so that it returns the response headers to add (an object, header name -> string value):
- requestOrigin is the request''s Origin header (a string such as "https://app.codedev.test"), or null when the request has no Origin header (curl, same-origin page loads).
- allowlist is an array of trusted origins.
- When requestOrigin is exactly equal to one of the allowlist entries (whole string, case as sent), return Access-Control-Allow-Origin set to that origin and Access-Control-Allow-Credentials set to "true".
- For every other value - unknown origins, look-alikes such as "https://app.codedev.test.evil.example", a different scheme or port, the string "null", or no Origin at all - return no Access-Control-* headers.
- Always include Vary: Origin, whatever the origin, because the response depends on the Origin header.
Header names are compared case-insensitively by the tests; values are compared exactly.', 'open', 'easy'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
