INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 1, 'A request is sent with cookies (credentials: "include"). Which values of Access-Control-Allow-Origin will the browser accept for it, and is "*" one of them?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 2, 'Look at what the function returns for an origin that is NOT in the allowlist, and at what it returns when there is no Origin header. Then ask what a shared cache would need to know if the headers change from one Origin to the next.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 3, 'A similar decision on a different header: a server answers in a language from the list ["en", "vi"] based on Accept-Language. For "vi" it answers in Vietnamese; for "vi-evil" it falls back to its default, because "vi-evil".startsWith("vi") is true but ["en", "vi"].includes("vi-evil") is false. Every answer carries Vary: Accept-Language, even the default one, because the cached response depends on that header.');
