INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 'Both CodeDev apps get an Allow-Origin header and credentials are allowed', '{"view":"basic","allowlist":["https://app.codedev.test","https://admin.codedev.test"],"requests":["https://app.codedev.test","https://admin.codedev.test"]}', '[{"allowOrigin":true,"allowCredentials":"true"},{"allowOrigin":true,"allowCredentials":"true"}]', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 'A request without an Origin header (curl, same-origin) gets no Access-Control headers', '{"view":"basic","allowlist":["https://app.codedev.test","https://admin.codedev.test"],"requests":[null]}', '[{"allowOrigin":false,"allowCredentials":null}]', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 'Allowed origins are echoed exactly, with credentials and Vary: Origin', '{"view":"full","allowlist":["https://app.codedev.test","https://admin.codedev.test"],"requests":["https://app.codedev.test","https://admin.codedev.test"]}', '[{"allowOrigin":"https://app.codedev.test","allowCredentials":"true","varyOrigin":true},{"allowOrigin":"https://admin.codedev.test","allowCredentials":"true","varyOrigin":true}]', 5, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 'A browser lets both apps read a credentialed response and blocks an unknown site', '{"view":"browser","allowlist":["https://app.codedev.test","https://admin.codedev.test"],"requests":["https://app.codedev.test","https://admin.codedev.test","https://evil.example"]}', '["readable","readable","blocked"]', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_212'), 'Look-alike, wrong-scheme, wrong-port and null origins get no Access-Control headers', '{"view":"full","allowlist":["https://app.codedev.test","https://admin.codedev.test"],"requests":["https://evil.example","https://app.codedev.test.evil.example","https://evilcodedev.test","https://codedev.test","http://app.codedev.test","https://app.codedev.test:8443","https://app.codedev.test/","null",""]}', '[{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true},{"allowOrigin":null,"allowCredentials":null,"varyOrigin":true}]', 5, false, true, 5),
