-- challenge chal_quiz_whf_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_whf_221', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-2-2' AND is_deleted = false LIMIT 1), 'http-caching-evidence-quiz', 'Read the caching evidence', 'Two responses from the CodeDev progress incident: one before the fix and one after. Decide whether each statement about what the browser does with them is true or false.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_221'), 'After the fix, GET https://api.codedev.test/me/progress answers:

HTTP/2 200
content-type: application/json
cache-control: private, no-cache
etag: "p17-v42"

{"userId":17,"completedLessons":12,"percent":40}

Statement: "Because of no-cache, the browser does not store this response, so every visit to the progress page downloads the full JSON body again."', 'single_choice'::question_type, 'False. no-cache does not forbid storing; that is no-store. no-cache means the browser may store the response but must validate it with the server before each reuse. Because the response has an ETag, the browser sends If-None-Match: "p17-v42" and, while nothing has changed, receives 304 Not Modified with no body and reuses the stored JSON. Reading no-cache as "do not cache" is the most common caching misconception.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
