FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_221'), 'Before the fix, the progress page ran fetch("https://api.codedev.test/me/progress", { credentials: "include" }) each time it opened. The first response, received at 09:00, was:

HTTP/2 200
content-type: application/json
cache-control: public, max-age=86400

At 11:00 the same day, the learner opens the progress page again in the same browser, without a hard reload and without DevTools.

Statement: "The browser may answer this fetch from its own cache without sending any request to the API, and the Network tab would list it as (disk cache) or (memory cache)."', 'single_choice'::question_type, 'True. max-age=86400 makes the stored response fresh for 24 hours. Two hours later its age is about 7200 seconds, well under 86400, so the browser is allowed to reuse it without contacting the server - no request, no log line on the API, and the old numbers on screen. DevTools shows such a response with (disk cache) or (memory cache) in the Size column and the stored status, 200. A common misconception is that a fetch() call always goes to the network; it goes through the HTTP cache like any other request.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_221') AND order_index = 2)
    RETURNING id
)
