-- challenge chal_coding_whf_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_whf_222', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-2-2' AND is_deleted = false LIMIT 1), 'read-cache-control', 'Read Cache-Control', 'The CodeDev team is auditing the Cache-Control header of every API response after the stale progress page incident. Write parseCacheControl(header), which reads one Cache-Control header value and returns exactly this object:

{ maxAge, noStore, noCache, private, public }

- maxAge: the max-age value as an integer number of seconds, or null when max-age is missing or its value is not a plain non-negative integer ("-1", "1.5", "60s", "abc", an empty value or no value at all). A value larger than 2147483648 is capped at 2147483648, as RFC 9111 recommends. A quoted value such as max-age="120" is accepted (120).
- noStore, noCache, private, public: true when that directive is present, false otherwise. A directive with an argument still counts: no-cache="Set-Cookie" sets noCache to true, private="Set-Cookie" sets private to true.

The header follows RFC 9111: directives are separated by commas, with optional spaces around them; directive names are case-insensitive (MAX-AGE, No-Store); a value may be a quoted string that itself contains commas (no-cache="Set-Cookie, Authorization" is one directive); empty items ("max-age=60,,private") and unknown directives (immutable, stale-while-revalidate=30, s-maxage=600) are ignored. s-maxage is a different directive: it never sets maxAge. A missing header (null or undefined) or an empty string gives { maxAge: null, noStore: false, noCache: false, private: false, public: false }.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
