INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 1, 'If you split private="Set-Cookie, Authorization", max-age=30 at every comma, how many pieces do you get, and how many of them are real directives?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 2, 'For each directive you need three steps: trim the spaces, lowercase the part before the first "=", and remove one pair of surrounding double quotes from the part after it. Only then decide whether the value of max-age is made of digits only - parseInt and Number both accept text that is not a plain integer.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 3, 'A similar parser for a different header: Keep-Alive: "Timeout=5, MAX=1000". Split it into items, trim each, split each item at its first "=" into a name and a value, lowercase the name, and check the value with /^\d+$/ before converting: "timeout" -> 5, "max" -> 1000. An item such as "timeout=5s" fails the check and is treated as missing rather than as 5.');
