VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'The incident header and the fixed header', '{"headers":["public, max-age=86400","private, no-cache"]}', '[{"maxAge":86400,"noStore":false,"noCache":false,"private":false,"public":true},{"maxAge":null,"noStore":false,"noCache":true,"private":true,"public":false}]', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'no-store, max-age=0 and a missing or empty header', '{"headers":["no-store","max-age=0, must-revalidate","",null]}', '[{"maxAge":null,"noStore":true,"noCache":false,"private":false,"public":false},{"maxAge":0,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false}]', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'Directive names are case-insensitive and spaces around items are ignored', '{"headers":["Max-Age=600 ,PRIVATE","  No-Cache ,   NO-STORE  ","Public,MAX-AGE=30"]}', '[{"maxAge":600,"noStore":false,"noCache":false,"private":true,"public":false},{"maxAge":null,"noStore":true,"noCache":true,"private":false,"public":false},{"maxAge":30,"noStore":false,"noCache":false,"private":false,"public":true}]', 5, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'Quoted values, including quoted lists that contain commas', '{"headers":["max-age=\"120\"","private=\"Set-Cookie\", no-cache=\"Set-Cookie, Authorization\", max-age=30","no-cache=\"Set-Cookie, public, Authorization\", max-age=5"]}', '[{"maxAge":120,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":30,"noStore":false,"noCache":true,"private":true,"public":false},{"maxAge":5,"noStore":false,"noCache":true,"private":false,"public":false}]', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'Invalid max-age values become null, and s-maxage never sets maxAge', '{"headers":["max-age=-1","max-age=1.5","max-age=60s","max-age=abc","max-age=","max-age","s-maxage=600, public","max-age=\"\""]}', '[{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":true},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false}]', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'Unknown directives and empty items are ignored', '{"headers":["stale-while-revalidate=30, immutable, max-age=31536000, public","max-age=60,,private,",", , no-transform"]}', '[{"maxAge":31536000,"noStore":false,"noCache":false,"private":false,"public":true},{"maxAge":60,"noStore":false,"noCache":false,"private":true,"public":false},{"maxAge":null,"noStore":false,"noCache":false,"private":false,"public":false}]', 5, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_whf_222'), 'Huge max-age values are capped at 2147483648, leading zeros are fine', '{"headers":["max-age=99999999999999999999","max-age=2147483648","max-age=2147483647","max-age=007"]}', '[{"maxAge":2147483648,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":2147483648,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":2147483647,"noStore":false,"noCache":false,"private":false,"public":false},{"maxAge":7,"noStore":false,"noCache":false,"private":false,"public":false}]', 5, false, true, 7);
