-- challenge chal_quiz_whf_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_whf_231', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-2-3' AND is_deleted = false LIMIT 1), 'cookies-401-403-quiz', 'Cookies, sessions and status codes', 'Three pieces of evidence from the CodeDev login incident: a Set-Cookie header, a teacher-only request from a learner, and a line from the API''s request log. Decide whether each statement is true or false.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231'), 'After the teammate''s change, the login response from https://api.codedev.test contains:

HTTP/2 200
set-cookie: session=s%3A9f2c...; Path=/; HttpOnly; SameSite=None

Statement: "The browser stores this cookie and, because of SameSite=None, sends it on every later request to api.codedev.test, including cross-site ones."', 'single_choice'::question_type, 'False. A cookie with SameSite=None must also carry the Secure attribute; current browsers reject a SameSite=None cookie without Secure, so this cookie is never stored (DevTools shows a warning on the Set-Cookie line, and Application > Cookies stays empty). The misconception is that SameSite=None is a harmless "allow everything" switch. Here it was not even needed: app.codedev.test and api.codedev.test are the same site, so SameSite=Lax cookies are sent on requests between them.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231'), 'A learner with a valid, unexpired session cookie (role: student) sends:

DELETE https://api.codedev.test/courses/42
Cookie: session=s%3A7a1b...

Only users with the teacher role may delete courses, and course 42 is listed publicly in the catalog.

Statement: "The API should answer 403 Forbidden, and logging in again with the same account would not change that answer."', 'single_choice'::question_type, 'True. The request is authenticated - the server knows who the learner is - but that user is not allowed to perform the action, which is exactly what 403 Forbidden means. RFC 9110 says the client should not repeat the request with the same credentials, so the web app should show an access-denied message instead of a login form. Answering 401 here is the common mistake: it tells the client to authenticate, and a client that redirects to login on 401 ends up in a loop. 404 would only make sense if the course''s existence were private, and course 42 is public.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231'), 'The API''s request log contains:

2026-10-20T08:14:03Z INFO GET /me 200 12ms user=17 cookie="session=s%3A9f2c4e..."

The session cookie is set with Secure, HttpOnly and SameSite=Lax.

Statement: "Because the cookie is HttpOnly, writing it to the log is harmless: JavaScript cannot read it, so nobody can reuse it."', 'single_choice'::question_type, 'False. HttpOnly only stops page scripts from reading the cookie through document.cookie. Anyone who can read the log can copy the value into a Cookie header (curl -H ''Cookie: session=...'') and act as user 17 until the session ends. Logs should carry the user id, route, status and a reason, and redact Cookie, Set-Cookie and Authorization headers; sessions that already leaked should be invalidated. The misconception is treating HttpOnly as general secrecy rather than protection from scripts in the page.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_whf_231') AND order_index = 3)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
