-- challenge chal_coding_whf_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_whf_312', (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-http-fundamentals') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-whf-3-1' AND is_deleted = false LIMIT 1), 'fetch-with-retry-limit', 'Retry with a limit', 'The progress page and the submissions client share one helper, fetchWithRetry(request, { fetch, sleep, retries = 3, baseDelayMs = 100 }). Rewrite it so it retries only failures that can go away on their own. Call fetch(request) with the request you were given. Retry when fetch rejects (network error, or TimeoutError from AbortSignal.timeout) - but rethrow an error named "AbortError" at once, because the user cancelled - and when the response status is 429, 502, 503 or 504. Return every other response immediately without retrying (2xx, 3xx, 400, 401, 403, 404, 409, 422, 500, 501 and so on). Make at most `retries` retries (at most retries + 1 calls to fetch). Before retry n (n starts at 1), await sleep(baseDelayMs * 2 ** (n - 1)) - 100, 200, 400 ms with the defaults - except when the retryable response has a Retry-After header made only of digits: then sleep that many seconds (seconds * 1000 ms). Any other Retry-After value, such as an HTTP-date, uses the backoff delay. When no retry is left, return the last response or rethrow the last error object. Use only the injected fetch and sleep: the tests replay scripted responses and record every delay.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
